# Get the script's directory
$scriptPath = Split-Path -Parent $MyInvocation.MyCommand.Path
$rootPath = Split-Path -Parent $scriptPath

# Set working directory to backend root
Set-Location $rootPath

# Create test environment file if it doesn't exist
$envTestPath = Join-Path $rootPath ".env.test"
if (-not (Test-Path $envTestPath)) {
    @"
NODE_ENV=test
PORT=3001
MONGODB_URI=mongodb://localhost:27017/healthcare-test
JWT_SECRET=test-secret-key
JWT_REFRESH_SECRET=test-refresh-secret-key
JWT_EXPIRES_IN=1h
JWT_REFRESH_EXPIRES_IN=7d
RATE_LIMIT_WINDOW_MS=900000
RATE_LIMIT_MAX=100
"@ | Out-File -FilePath $envTestPath -Encoding UTF8
    Write-Host "Created .env.test file"
}

# Check if MongoDB is running
$mongoProcess = Get-Process -Name "mongod" -ErrorAction SilentlyContinue
if (-not $mongoProcess) {
    Write-Host "MongoDB is not running. Please start MongoDB before running tests."
    Write-Host "You can start MongoDB by running 'mongod' in a separate terminal."
    exit 1
}

# Install dependencies if node_modules doesn't exist
if (-not (Test-Path "node_modules")) {
    Write-Host "Installing dependencies..."
    npm install
    if ($LASTEXITCODE -ne 0) {
        Write-Host "Failed to install dependencies"
        exit 1
    }
}

# Create logs directory if it doesn't exist
$logsPath = Join-Path $rootPath "logs"
if (-not (Test-Path $logsPath)) {
    New-Item -ItemType Directory -Path $logsPath | Out-Null
    Write-Host "Created logs directory"
}

# Build TypeScript files
Write-Host "Building TypeScript files..."
npm run backend:build
if ($LASTEXITCODE -ne 0) {
    Write-Host "Failed to build TypeScript files"
    exit 1
}

Write-Host "Test environment setup complete!"
Write-Host "You can now run tests using: npm test" 